// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TxnMutationJournalTest {
	@Test
	void spillsPrimitiveRecordsAndReplaysThemInOrder(@TempDir Path directory) throws Exception {
		byte[] namespaceSnapshot = new byte[96 * 1024];
		for (int i = 0; i < namespaceSnapshot.length; i++) {
			namespaceSnapshot[i] = (byte) (i * 31);
		}

		int[] stores = { 0 };
		boolean[] namespaceSeen = { false };
		boolean[] removeSeen = { false };
		try (TxnMutationJournal journal = new TxnMutationJournal(directory)) {
			for (int i = 0; i < 4096; i++) {
				journal.appendStore(i, i + 1L, i + 2L, i % 23, (i & 1) == 0);
			}
			journal.appendNamespaceSnapshot(namespaceSnapshot);
			journal.appendRemove(10, 11, 12, 13, false);
			assertEquals(4098, journal.recordCount());
			try (var files = Files.list(directory)) {
				assertEquals(1, files.count(), "The bounded in-memory journal should have spilled exactly one file");
			}

			journal.replay(new TxnMutationJournal.ReplayAction() {
				@Override
				public boolean store(long subj, long pred, long obj, long context, boolean explicit, long record) {
					int expected = stores[0]++;
					assertEquals(expected, subj);
					assertEquals(expected + 1L, pred);
					assertEquals(expected + 2L, obj);
					assertEquals(expected % 23, context);
					assertEquals((expected & 1) == 0, explicit);
					return true;
				}

				@Override
				public void remove(long subj, long pred, long obj, long context, boolean explicit) {
					assertEquals(4096, stores[0]);
					assertEquals(10, subj);
					assertEquals(11, pred);
					assertEquals(12, obj);
					assertEquals(13, context);
					assertFalse(explicit);
					removeSeen[0] = true;
				}

				@Override
				public void writeNamespaceSnapshot(byte[] snapshot) {
					assertEquals(4096, stores[0]);
					assertArrayEquals(namespaceSnapshot, snapshot);
					assertFalse(removeSeen[0], "The namespace event must retain its original mutation order");
					namespaceSeen[0] = true;
				}
			});
		}

		assertEquals(4096, stores[0]);
		assertTrue(namespaceSeen[0]);
		assertTrue(removeSeen[0]);
		try (var files = Files.list(directory)) {
			assertFalse(files.findAny().isPresent(), "Closing the journal should remove its spill file");
		}
	}
}
